				}

			#endif

			#ifdef GLOWING_ENTITY_FIX

				if (isGlowing > 0.9975) {
					const vec2 glowOutlineOffsets[16] = vec2[16](vec2( 0.0, -1.0),
																 vec2(-1.0,  0.0),
																 vec2( 1.0,  0.0),
																 vec2( 0.0,  1.0),
																 vec2(-1.0, -2.0),
																 vec2( 0.0, -2.0),
																 vec2( 1.0, -2.0),
																 vec2(-2.0, -1.0),
																 vec2( 2.0, -1.0),
																 vec2(-2.0,  0.0),
																 vec2( 2.0,  0.0),
																 vec2(-2.0,  1.0),
																 vec2( 2.0,  1.0),
																 vec2(-1.0,  2.0),
																 vec2( 0.0,  2.0),
																 vec2( 1.0,  2.0)
					);

					#ifdef GLOWING_ENTITY_RGB
						vec3 colorGlow = clamp01(vec3(hue2(frameTimeCounter * 0.1)));
            				 colorGlow = pow(colorGlow, vec3(2.2)) * 1.0 * 0.5;
