#if !(SHADERLOD_REFINEMENT_ADAPTER == 1 && SHADERLOD_ASTRA_EARLY_CONTEXT() && defined OVERWORLD && !defined DEBUG_TERRAIN && !defined DETECTEUR_CAVE && !defined DISTANT_HORIZONS && !defined VOXY)
#define shaderlodAstraSample2D(s,p) texture2D(s,p)
