						#endif

					float aoSquared = pow2(ao);
						shadow *= aoSquared;
						fresnel3 *= aoSquared * smoothness * smoothness;

						if (smoothness > 0.0) {
							vec4 reflection = vec4(0.0);
							vec3 skyReflection = vec3(0.0);
							float reflectionMask = 0.0;

							float ssrMask = clamp01(length(fresnel3) * 400.0 - 1.0);
